(function () {
 'use strict';
 function $(id) {
 return document.getElementById(id);
 }
 function escapeHtml(value) {
 return String(value == null ? '' : value)
 .replace(/&/g, '&amp;')
 .replace(/</g, '&lt;')
 .replace(/>/g, '&gt;')
 .replace(/"/g, '&quot;')
 .replace(/'/g, '&#39;');
 }
 function truncate(text, maxLen) {
 if (!text || text.length <= maxLen) return text;
 return text.slice(0, maxLen - 1).trimEnd() + '...';
 }
 function buildPreview(entry) {
 var timeEl = entry.querySelector('time');
 var categoryEl = entry.querySelector('.entry-category');
 var titleEl = entry.querySelector('.entry-title');
 var firstParagraph = entry.querySelector('.entry-body p');
 var tags = Array.prototype.slice.call(entry.querySelectorAll('.entry-tags .tag')).slice(0, 3);
 if (!timeEl || !titleEl) {
 return null;
 }
 var dateText = (timeEl.textContent || '').trim();
 var dateValue = timeEl.getAttribute('datetime') || '';
 var categoryText = categoryEl ? (categoryEl.textContent || '').trim() : 'Journal';
 var titleText = (titleEl.textContent || '').trim();
 var paragraphText = firstParagraph ? (firstParagraph.textContent || '').trim() : '';
 var tagsHtml = tags.map(function (tag) {
 return '<span class="tag">' + escapeHtml((tag.textContent || '').trim()) + '</span>';
 }).join('');
 return {
 id: entry.id || '',
 html:
 '<div class="entry-meta">' +
 '<time datetime="' + escapeHtml(dateValue) + '">' + escapeHtml(dateText) + '</time>' +
 '<span class="entry-category">' + escapeHtml(categoryText) + '</span>' +
 '</div>' +
 '<h3 class="entry-title">' + escapeHtml(titleText) + '</h3>' +
 '<div class="entry-body"><p>' + escapeHtml(truncate(paragraphText, 360)) + '</p></div>' +
 (tagsHtml ? '<div class="entry-tags">' + tagsHtml + '</div>' : '')
 };
 }
 function syncLatestJournal() {
 var card = $('journal-preview-card');
 var link = $('journal-preview-link');
 if (!card || !link) return;
 fetch('journal.html', { cache: 'no-store' })
 .then(function (response) {
 if (!response.ok) throw new Error('journal_fetch_' + response.status);
 return response.text();
 })
 .then(function (html) {
 var parser = new DOMParser();
 var doc = parser.parseFromString(html, 'text/html');
 var newestEntry = doc.querySelector('.journal-feed .journal-entry');
 if (!newestEntry) return;
 var preview = buildPreview(newestEntry);
 if (!preview) return;
 card.innerHTML = preview.html;
 link.setAttribute('href', 'journal.html');
 })
 .catch(function () {
 // Keep static fallback content already present in index.html.
 });
 }
 if (document.readyState === 'loading') {
 document.addEventListener('DOMContentLoaded', syncLatestJournal);
 } else {
 syncLatestJournal();
 }
})();
